#include <iostream>
#include <vector>
#include <iomanip>

void print1D(const std::vector<int>& arr) {
    for (size_t i = 0; i < arr.size(); ++i) {
        std::cout << "array[" << i << "] = " << arr[i] << "\n";
    }
}

void print2D(const std::vector<int>& matrix, size_t rows, size_t cols) {
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            std::cout << std::setw(5) << matrix[r * cols + c];
        }
        std::cout << "\n";
    }
}

int main() {
    size_t size1D = 4;
    size_t r1 = 2, c1 = 3;

    std::vector<int> arr1D(size1D);
    for (size_t i = 0; i < size1D; ++i) {
        arr1D[i] = static_cast<int>(i * i);
    }

    std::vector<int> mat1(r1 * c1);
    for (size_t r = 0; r < r1; ++r) {
        for (size_t c = 0; c < c1; ++c) {
            mat1[r * c1 + c] = static_cast<int>(r + c);
        }
    }

    std::cout << "One-dimensional array:\n";
    print1D(arr1D);

    std::cout << "\nFirst two-dimensional array:\n";
    print2D(mat1, r1, c1);

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>

int main() {
    // 1. Memory-safe string input without fixed-buffer overflow risk
    std::string safeText = "User-controlled input: %s %d %n";

    // 2. Type-safe output preventing format string vulnerabilities
    // In C: printf("%s\n", safeText.c_str()); never printf(safeText.c_str());
    std::cout << "Safe printing: " << safeText << "\n";

    // 3. Array bounds checking using at()
    std::vector<int> numbers = {10, 20, 30};
    size_t validIndex = 1;
    size_t invalidIndex = 5;

    if (validIndex < numbers.size()) {
        std::cout << "Element at " << validIndex << ": " << numbers[validIndex] << "\n";
    }

    try {
        std::cout << numbers.at(invalidIndex) << "\n";
    } catch (const std::out_of_range&) {
        std::cout << "Caught bounds error safely: index " << invalidIndex << " is out of bounds\n";
    }

    return 0;
}
